def split_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [raw]
	out = []
	for item in raw or []:
		parts = []
		for part in str(item).split("|"):
			parts.append(part.strip())
		if parts and parts[0]:
			out.append(parts)
	return out


def num(value):
	try:
		text = str(value).replace(",", "").replace("$", "").replace("%", "").strip()
		if not text:
			return None
		return float(text)
	except Exception:
		return None


def money(value, cur):
	digits = str(int(round(value)))
	out = ""
	while len(digits) > 3:
		out = "," + digits[-3:] + out
		digits = digits[:-3]
	return cur + digits + out


def slugify(text):
	out = ""
	for ch in str(text or "").lower():
		out = out + (ch if ch.isalnum() else "-")
	return out


def fixed(value):
	return str(round(value, 2))

def axis_ticks(lo, hi):
	if lo is None or lo <= 0:
		lo = 1.0
	if hi is None or hi <= lo:
		hi = lo * 10
	ticks = [lo]
	power = 1.0
	while power * 10 <= lo:
		power = power * 10
	while power > lo:
		power = power / 10
	done = False
	guard = 0
	while not done and guard < 40:
		for mult in [1, 2.5, 5]:
			value = mult * power
			if value >= hi:
				done = True
				break
			if value > lo:
				ticks.append(value)
		power = power * 10
		guard = guard + 1
	ticks.append(hi)
	return ticks


def axis_pos(value, ticks):
	n = len(ticks)
	if n < 2 or value <= ticks[0]:
		return 0.0
	if value >= ticks[n - 1]:
		return 100.0
	i = 0
	while i < n - 2 and value > ticks[i + 1]:
		i = i + 1
	frac = (value - ticks[i]) / (ticks[i + 1] - ticks[i])
	return (i + frac) / (n - 1) * 100.0


def tick_label(value, cur):
	if value >= 1000000:
		x = value / 1000000.0
		suffix = "M"
	elif value >= 1000:
		x = value / 1000.0
		suffix = "K"
	else:
		x = value
		suffix = ""
	if x == int(x):
		shown = str(int(x))
	else:
		shown = str(round(x, 1))
	return cur + shown + suffix


def tape_ticks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		x = 0.0 if n < 2 else i * 100.0 / (n - 1)
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		crowded = "true" if (n > 4 and (i == 1 or i == n - 2)) else "false"
		out.append({"x": str(round(x, 4)) + "%", "label": tick_label(ticks[i], cur), "major": "true", "edge": edge, "crowded": crowded})
		if i < n - 1:
			out.append({"x": str(round((i + 0.5) * 100.0 / (n - 1), 4)) + "%", "label": "", "major": "false", "edge": "mid", "crowded": "true"})
	return out


def axis_marks(ticks, cur, tick_label):
	out = []
	n = len(ticks)
	for i in range(n):
		edge = "mid"
		if i == 0:
			edge = "start"
		if i == n - 1:
			edge = "end"
		out.append({
			"x": str(round(0.0 if n < 2 else i * 100.0 / (n - 1), 4)) + "%",
			"label": tick_label(ticks[i], cur),
			"edge": edge,
			"crowded": "true" if (n > 4 and (i == 1 or i == n - 2)) else "false",
		})
	return out

cur = str(props.get("currency") or "$")
start = num(props.get("axis_min")) or 1000.0
stop = num(props.get("axis_max")) or 5000.0
step = num(props.get("step")) or 500.0
fine = num(props.get("fine_step")) or 100.0
if stop <= start:
	stop = start + step * 8
span = stop - start
n = int(round(span / step)) + 1
if n > 41:
	n = 41
ticks = []
for k in range(n):
	value = start + k * step
	edge = "mid"
	if k == 0:
		edge = "start"
	if k == n - 1:
		edge = "end"
	ticks.append({"x": str(round(min((value - start) / span * 100.0, 100.0), 4)) + "%", "label": tick_label(value, cur), "edge": edge, "alt": "true" if k % 2 == 1 else "false"})
was_low = num(props.get("usual_low")) or start
was_high = num(props.get("usual_high")) or stop
price = num(props.get("fixed_price")) or (was_low + was_high) / 2
component.ticks = ticks
component.lo = fixed(max(0.0, min(100.0, (was_low - start) / span * 100.0)))
component.hi = fixed(max(0.0, min(100.0, (was_high - start) / span * 100.0)))
component.typ = fixed(max(0.0, min(100.0, (price - start) / span * 100.0)))
component.fine = str(round(fine / span * 100.0, 4)) + "%"
component.label = "A closer stretch of the tape, " + money(start, cur) + " to " + money(stop, cur) + ": a usual range of " + money(was_low, cur) + " to " + money(was_high, cur) + " closes to one fixed price, " + money(price, cur) + ", after a free look"
